import java.util.*;
public class Main {
    static char[][] a = new char[20][20];
    static char[][] b = new char[20][20];
    static class Pair {
        int first, second;
        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }
    static Queue<Pair> q = new LinkedList<>();
    static int[][] Dis = new int[20][20];
    static int[][][][] dis = new int[11][11][11][11];
    static int[] fx = {-1, 1, 0, 0};
    static int[] fy = {0, 0, -1, 1};
    static class Edge {
        int u, v, fl, c, n;
        Edge(int u, int v, int fl, int c, int n) {
            this.u = u; this.v = v; this.fl = fl; this.c = c; this.n = n;
        }
    }
    static List<Edge> e = new ArrayList<>();
    static int[] head = new int[505];
    static int[] p = new int[505];
    static int[] v = new int[505];
    static int s = 501;
    static int t = 502;
    static long ans = 0;
    static int n, m;
    static int[] dep = new int[505];

    static void add(int u, int v, int w) {
        e.add(new Edge(u, v, 0, w, head[u]));
        head[u] = e.size() - 1;
        e.add(new Edge(v, u, 0, 0, head[v]));
        head[v] = e.size() - 1;
    }

    static boolean Find() {
        Arrays.fill(v, 0);
        Arrays.fill(dep, 0);
        Queue<Integer> qf = new LinkedList<>();
        qf.offer(s);
        v[s] = 1;
        dep[s] = 1;
        while (!qf.isEmpty()) {
            int x = qf.poll();
            for (int i = head[x]; i != -1; i = e.get(i).n) {
                Edge edge = e.get(i);
                if (v[edge.v] == 0 && edge.fl < edge.c) {
                    p[edge.v] = i;
                    qf.offer(edge.v);
                    v[edge.v] = 1;
                    dep[edge.v] = dep[x] + 1;
                    if (edge.v == t) return true;
                }
            }
        }
        return false;
    }

    static int dfs(int x, int now) {
        if (x == t || now == 0) return now;
        int t_now = now;
        for (int i = head[x]; i != -1; i = e.get(i).n) {
            Edge edge = e.get(i);
            if (edge.c > edge.fl && dep[edge.v] == dep[x] + 1) {
                int delta = dfs(edge.v, Math.min(t_now, edge.c - edge.fl));
                if (delta == 0) dep[edge.v] = 0;
                e.set(i, new Edge(edge.u, edge.v, edge.fl + delta, edge.c, edge.n));
                int rev = i ^ 1;
                e.set(rev, new Edge(e.get(rev).u, e.get(rev).v, e.get(rev).fl - delta, e.get(rev).c, e.get(rev).n));
                t_now -= delta;
                if (t_now == 0) break;
            }
        }
        return now - t_now;
    }

    static void dinic() {
        while (Find()) {
            ans += dfs(s, Integer.MAX_VALUE);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int t_input = sc.nextInt(); // the variable 't' in original code
        for (int i = 0; i <= 504; i++) {
            head[i] = -1;
        }
        for (int i = 1; i <= n; i++) {
            Arrays.fill(Dis[i], 10000);
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                a[i][j] = line.charAt(j - 1);
                if (a[i][j] == 'Z') {
                    q.offer(new Pair(i, j));
                    Dis[i][j] = 0;
                }
                if (a[i][j] <= '9') {
                    add(s, (i - 1) * n + j, a[i][j] - '0');
                }
            }
        }
        while (!q.isEmpty()) {
            Pair p_q = q.poll();
            int x = p_q.first, y = p_q.second;
            for (int i = 0; i < 4; i++) {
                int nx = x + fx[i], ny = y + fy[i];
                if (nx > 0 && ny > 0 && nx <= n && ny <= n && a[nx][ny] <= '9' && Dis[nx][ny] > Dis[x][y] + 1) {
                    Dis[nx][ny] = Dis[x][y] + 1;
                    q.offer(new Pair(nx, ny));
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (a[i][j] > '9') continue;
                for (int k = 1; k <= n; k++) {
                    for (int l = 1; l <= n; l++) {
                        dis[i][j][k][l] = 10000;
                    }
                }
                q.offer(new Pair(i, j));
                dis[i][j][i][j] = 0;
                boolean[][] visited = new boolean[20][20];
                while (!q.isEmpty()) {
                    Pair p_q2 = q.poll();
                    int x = p_q2.first, y = p_q2.second;
                    for (int f = 0; f < 4; f++) {
                        int nx = x + fx[f], ny = y + fy[f];
                        if (nx > 0 && ny > 0 && nx <= n && ny <= n && a[nx][ny] <= '9') {
                            if (dis[i][j][nx][ny] > dis[i][j][x][y] + 1 && dis[i][j][x][y] < Dis[x][y]) {
                                dis[i][j][nx][ny] = dis[i][j][x][y] + 1;
                                q.offer(new Pair(nx, ny));
                            }
                        }
                    }
                }
                for (int k = 1; k <= n; k++) {
                    for (int l = 1; l <= n; l++) {
                        int minDist = Math.min(Dis[k][l], t_input);
                        if (dis[i][j][k][l] <= minDist) {
                            add((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
                        }
                    }
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            String line_b = sc.next();
            for (int j = 1; j <= n; j++) {
                b[i][j] = line_b.charAt(j - 1);
                if (b[i][j] <= '9') {
                    add((i - 1) * n + j + 100, t, b[i][j] - '0');
                }
            }
        }
        dinic();
        System.out.println(ans);
    }
}
